// ExactfiniteL algebra + ALL22 sourceideal membership U^N. No GB/points.
#include <flint/fmpq.h>
#include <flint/fmpq_poly.h>
#include <flint/fmpq_mpoly.h>
#include <flint/fmpq_mat.h>
#include <algorithm>
#include <array>
#include <cassert>
#include <chrono>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;chrono::steady_clock::time_point begin_time;fmpq_mpoly_ctx_t ctx;
void tick(){assert(chrono::duration<double>(chrono::steady_clock::now()-begin_time).count()<50);}
struct E{fmpq_poly_t p;E(){fmpq_poly_init(p);}E(const E&x):E(){fmpq_poly_set(p,x.p);}E(E&&x):E(){fmpq_poly_swap(p,x.p);}E&operator=(E x){fmpq_poly_swap(p,x.p);return*this;}~E(){fmpq_poly_clear(p);}};
E e_modulus;long en;
E eo(){E p;fmpq_poly_one(p.p);return p;}E ea(const E&a,const E&b){E p;fmpq_poly_add(p.p,a.p,b.p);return p;}E neg(const E&a){E p;fmpq_poly_neg(p.p,a.p);return p;}bool eq(const E&a,const E&b){return fmpq_poly_equal(a.p,b.p);}E er(const E&a){E p;fmpq_poly_rem(p.p,a.p,e_modulus.p);return p;}E em(const E&a,const E&b){E p;fmpq_poly_mul(p.p,a.p,b.p);tick();return er(p);}E es(const E&a,const fmpq_t c){E p;fmpq_poly_scalar_mul_fmpq(p.p,a.p,c);return p;}E ediv(const E&a,const E&b){E q,r;fmpq_poly_divrem(q.p,r.p,a.p,b.p);assert(fmpq_poly_is_zero(r.p));E z;fmpq_poly_mul(z.p,q.p,b.p);assert(eq(z,a));return q;}
struct P{fmpq_mpoly_t p;P(){fmpq_mpoly_init(p,ctx);}P(const P&x):P(){fmpq_mpoly_set(p,x.p,ctx);}P(P&&x):P(){fmpq_mpoly_swap(p,x.p,ctx);}~P(){fmpq_mpoly_clear(p,ctx);}};
void readE(istream&f,E&p){long n;f>>n;assert(n>=0);fmpq_t c;fmpq_init(c);for(long i=0;i<n;i++){long j;string s;f>>j>>s;assert(j>=0&&!fmpq_set_str(c,s.c_str(),10));fmpq_canonicalise(c);fmpq_poly_set_coeff_fmpq(p.p,j,c);}fmpq_clear(c);}
void readP(istream&f,P&p){long n;f>>n;assert(n>=0);fmpq_t c;fmpq_init(c);ulong x[3];for(long i=0;i<n;i++){string s;f>>s>>x[0]>>x[1]>>x[2];assert(!fmpq_set_str(c,s.c_str(),10));fmpq_canonicalise(c);fmpq_mpoly_push_term_fmpq_ui(p.p,c,x,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);fmpq_clear(c);}
void je(ostream&o,const E&p){o<<'[';fmpq_t c;fmpq_init(c);bool first=true;for(long i=fmpq_poly_degree(p.p);i>=0;i--){fmpq_poly_get_coeff_fmpq(c,p.p,i);if(fmpq_is_zero(c))continue;if(!first)o<<',';first=false;char*s=fmpq_get_str(nullptr,10,c);o<<'['<<i<<",\""<<s<<"\"]";flint_free(s);}o<<']';fmpq_clear(c);assert(o.tellp()<31*1024*1024);}
using A=array<E,4>;array<E,4>h;
A ao(){A p;p[0]=eo();return p;}A aa(const A&a,const A&b){A p;for(int i=0;i<4;i++)p[i]=ea(a[i],b[i]);return p;}A as(const A&a,const E&s){A p;for(int i=0;i<4;i++)p[i]=em(a[i],s);return p;}A am(const A&a,const A&b){array<E,7>v;for(int i=0;i<4;i++)for(int j=0;j<4;j++)v[i+j]=ea(v[i+j],em(a[i],b[j]));for(int j=6;j>=4;j--){E t=v[j];for(int i=0;i<4;i++)v[j-4+i]=ea(v[j-4+i],neg(em(t,h[i])));v[j]=E();}A out;for(int i=0;i<4;i++)out[i]=v[i];return out;}bool aeq(const A&a,const A&b){for(int i=0;i<4;i++)if(!eq(a[i],b[i]))return false;return true;}A apow(A a,long n){A r=ao();while(n){if(n&1)r=am(r,a);n>>=1;if(n)a=am(a,a);}return r;}
void ja(ostream&o,const A&a){o<<'[';for(int j=0;j<4;j++){if(j)o<<',';je(o,a[j]);}o<<']';}
vector<E>apowers,epowers;vector<A>dpowers;
E evaluate_hcoefficient(const P&p,int d){E r;fmpq_t c;fmpq_init(c);ulong ex[3];for(long i=0;i<fmpq_mpoly_length(p.p,ctx);i++){fmpq_mpoly_get_term_exp_ui(ex,p.p,i,ctx);if(ex[2]!=(ulong)d)continue;fmpq_mpoly_get_term_coeff_fmpq(c,p.p,i,ctx);r=ea(r,es(em(apowers.at(ex[0]),epowers.at(ex[1])),c));}fmpq_clear(c);return r;}
A evaluate(const P&p){A r;fmpq_t c;fmpq_init(c);ulong ex[3];for(long i=0;i<fmpq_mpoly_length(p.p,ctx);i++){fmpq_mpoly_get_term_exp_ui(ex,p.p,i,ctx);fmpq_mpoly_get_term_coeff_fmpq(c,p.p,i,ctx);E co=es(em(apowers.at(ex[0]),epowers.at(ex[1])),c);r=aa(r,as(dpowers.at(ex[2]),co));}fmpq_clear(c);return r;}
A basis(long b){A r;long i=b%en,j=b/en;fmpq_poly_set_coeff_si(r[j].p,i,1);return r;}
void setcol(fmpq_mat_t M,long j,const A&a){for(int k=0;k<4;k++)for(long i=0;i<en;i++)fmpq_poly_get_coeff_fmpq(fmpq_mat_entry(M,k*en+i,j),a[k].p,i);}
A readcol(const fmpq_mat_t X,long start){A r;for(int k=0;k<4;k++)for(long i=0;i<en;i++)fmpq_poly_set_coeff_fmpq(r[k].p,i,fmpq_mat_entry(X,start+k*en+i,0));return r;}
int main(int argc,char**argv){assert(argc==3);begin_time=chrono::steady_clock::now();fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{
 ifstream f(argv[1]);E originalS,aL;readE(f,originalS);readE(f,aL);P Hclear,U;readP(f,Hclear);readP(f,U);int count;f>>count;assert(count==22);vector<P>Psource(count);for(auto&p:Psource)readP(f,p);string extra;assert(!(f>>extra));
 vector<E>removed,after,aquot;E current=originalS;while(true){E g;fmpq_poly_gcd(g.p,current.p,aL.p);if(fmpq_poly_degree(g.p)<=0)break;removed.push_back(g);current=ediv(current,g);after.push_back(current);aquot.push_back(ediv(aL,g));assert(removed.size()<=10);}e_modulus=current;en=fmpq_poly_degree(e_modulus.p);assert(en>0&&en<=9);long N=4*en;E gcd,bezS,bezA;fmpq_poly_xgcd(gcd.p,bezS.p,bezA.p,e_modulus.p,aL.p);assert(fmpq_poly_is_one(gcd.p));E raw0,raw1;fmpq_poly_mul(raw0.p,bezS.p,e_modulus.p);fmpq_poly_mul(raw1.p,bezA.p,aL.p);assert(eq(ea(raw0,raw1),eo()));E ainv=er(bezA);assert(eq(em(ainv,aL),eo()));
 apowers.push_back(eo());epowers.push_back(eo());E ep;fmpq_poly_set_coeff_si(ep.p,1,1);for(int i=1;i<=16;i++){apowers.push_back(em(apowers.back(),aL));epowers.push_back(em(epowers.back(),ep));}E inv5=eo();for(int i=0;i<5;i++)inv5=em(inv5,ainv);array<E,5>hclear,hnorm;for(int i=0;i<=4;i++){hclear[i]=evaluate_hcoefficient(Hclear,i);hnorm[i]=em(hclear[i],inv5);}assert(eq(hnorm[4],eo()));for(int i=0;i<4;i++)h[i]=hnorm[i];
 dpowers.push_back(ao());A dp;dp[1]=eo();for(int i=1;i<=16;i++)dpowers.push_back(am(dpowers.back(),dp));vector<A>images;for(auto&p:Psource)images.push_back(evaluate(p));A ui=evaluate(U),target=apow(ui,N);cerr<<"ALGEBRA_AND_ALL22_SOURCE_IMAGES_PASS dimension="<<N<<"\n";
 vector<A>cols;fmpq_mat_t M,T,X,check;fmpq_mat_init(M,N,count*N);fmpq_mat_init(T,N,1);fmpq_mat_init(X,count*N,1);fmpq_mat_init(check,N,1);long nz=0,maxbits=0;for(int i=0;i<count;i++)for(long b=0;b<N;b++){A col=am(images[i],basis(b));cols.push_back(col);setcol(M,i*N+b,col);}setcol(T,0,target);for(long i=0;i<N;i++)for(long j=0;j<count*N;j++){const fmpq*q=fmpq_mat_entry(M,i,j);nz+=!fmpq_is_zero(q);maxbits=max(maxbits,(long)(fmpz_bits(fmpq_numref(q))+fmpz_bits(fmpq_denref(q))));}assert(nz<=150000);assert(nz*(150+maxbits*31/100)<31*1024*1024);cerr<<"MATRIX_PREFLIGHT_PASS nonzero="<<nz<<" coeffbits="<<maxbits<<"\n";tick();int solved=fmpq_mat_can_solve_fraction_free(X,M,T);vector<A>witness;
 if(solved){fmpq_mat_mul(check,M,X);assert(fmpq_mat_equal(check,T));A dot;for(int i=0;i<count;i++){witness.push_back(readcol(X,i*N));dot=aa(dot,am(witness.back(),images[i]));}assert(aeq(dot,target));}cerr<<"QQ_MEMBERSHIP_DONE solved="<<solved<<"\n";
 ofstream o(argv[2]);o<<"{\"dimension_N\":"<<N<<",\"base_e_degree\":"<<en<<",\"a_zero_clopen_removal_steps\":[";for(int i=0;i<(int)removed.size();i++){if(i)o<<',';o<<"{\"removed_factor\":";je(o,removed[i]);o<<",\"remaining_after\":";je(o,after[i]);o<<",\"aL_quotient\":";je(o,aquot[i]);o<<'}';}o<<"],\"remaining_e_modulus\":";je(o,e_modulus);o<<",\"aL_inverse\":";je(o,ainv);o<<",\"modulus_aL_Bezout1\":[";je(o,bezS);o<<',';je(o,bezA);o<<"],\"Hclear_coefficients\":[";for(int i=0;i<5;i++){if(i)o<<',';je(o,hclear[i]);}o<<"],\"H_normalized_monic_coefficients\":[";for(int i=0;i<5;i++){if(i)o<<',';je(o,hnorm[i]);}o<<"],\"all22_original_source_images\":[";for(int i=0;i<count;i++){if(i)o<<',';ja(o,images[i]);}o<<"],\"U_image\":";ja(o,ui);o<<",\"target_U_power_N\":";ja(o,target);o<<",\"all22N_ideal_matrix_columns\":[";for(int i=0;i<(int)cols.size();i++){if(i)o<<',';ja(o,cols[i]);}o<<"],\"membership_solved\":"<<(solved?"true":"false")<<",\"source22_cofactor_witness\":[";for(int i=0;i<(int)witness.size();i++){if(i)o<<',';ja(o,witness[i]);}o<<"],\"matrix_nonzero_entries\":"<<nz<<",\"matrix_max_numerator_plus_denominator_bits\":"<<maxbits<<",\"solve_backend\":\"fmpq_mat_can_solve_fraction_free\",\"all_source_membership_identities_checked\":true,\"native_seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-begin_time).count()<<"}\n";
 fmpq_mat_clear(M);fmpq_mat_clear(T);fmpq_mat_clear(X);fmpq_mat_clear(check);
}apowers.clear();epowers.clear();dpowers.clear();for(auto&x:h)x=E();e_modulus=E();fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
